using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Windows.Forms;

internal static class BulletSystemTests
{
    private static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
    private static void Near(double a,double b,string message){Check(Math.Abs(a-b)<.0001,message+": "+a+" != "+b);}
    private static Track Emitter(string id="e"){return new Track{id=id,kind="emitter",name=id,sprite="sprBullet",start=0,end=0,x=0,y=0,count=1,interval=10,speed=4,spread=0,life=200,advancedBullets=true};}
    private static EditorState Scene(params Track[] tracks){var s=new EditorState{duration=1000,tracks=tracks.ToList()};Motion.Normalize(s);return s;}
    [STAThread] public static int Main(string[] args)
    {
        try{
            if(args[0]=="--sample"){var sampleState=Json.Read<EditorState>(File.ReadAllText(args[1]));Motion.Normalize(sampleState);var sampleWorld=new BulletWorld(sampleState);sampleWorld.Seek(Int32.Parse(args[2]));File.WriteAllText(args[3],Json.Write(sampleWorld.bullets.Where(row=>row.birth<=sampleWorld.Frame).Select(row=>new{source=row.source.id,birth=row.birth,index=row.index,x=row.x,y=row.y,direction=row.direction,speed=row.speed,scale=row.scale,alpha=row.alpha,generation=row.generation}).ToArray()));return 0;}
            Application.EnableVisualStyles();string scratch=args[0],root=args[1];Directory.CreateDirectory(scratch);
            var t=Emitter();t.bulletActions.Add(new BulletAction{type="speed",start=0,duration=4,from=4,to=0});t.bulletActions.Add(new BulletAction{type="aim",start=6,duration=0,to=0});t.bulletActions.Add(new BulletAction{type="speed",start=6,duration=2,from=0,to=4});var state=Scene(t);state.nativeTest=new NativeTestPosition{x=0,y=100};Motion.Normalize(state);var world=new BulletWorld(state);world.Seek(4);Near(world.bullets[0].x,6,"Deceleration uses per-bullet age");world.Seek(8);Near(world.bullets[0].speed,4,"Acceleration completes");Check(world.bullets[0].y>5,"Aim uses player position");double x=world.bullets[0].x,y=world.bullets[0].y;world.Seek(1);world.Seek(8);Near(world.bullets[0].x,x,"Backward seek deterministic X");Near(world.bullets[0].y,y,"Backward seek deterministic Y");
            var a=Emitter("red");a.tag="red";var b=Emitter("blue");b.tag="blue";b.end=20;var command=new Track{id="stop",kind="control",start=2,end=2,targetTag="red",controlValue=0};world=new BulletWorld(Scene(a,b,command));world.Seek(4);Near(world.bullets.First(q=>q.source.id=="red").x,4,"Tag command stops only matching existing bullets");Near(world.bullets.First(q=>q.source.id=="blue").x,16,"Other tags unaffected");
            var child=Emitter("child");child.enabled=false;child.bulletActions.Add(new BulletAction{type="alpha",start=0,duration=0,to=.25});t=Emitter();t.bulletActions.Add(new BulletAction{type="split",start=2,duration=0,count=3,spread=30,childSpeed=2,templateId=child.id});world=new BulletWorld(Scene(t,child));world.Seek(2);Check(world.bullets.Count==4,"One mother plus three children");Check(world.bullets.Where(q=>q.generation==1).All(q=>q.alpha==.25),"Child age-zero actions execute at birth");Near(world.bullets[1].x,8,"Children born at mother position after movement");
            t=Emitter();t.count=3;t.indexDelay=2;t.emissionShape="line";t.emitWidth=100;t.speed=0;world=new BulletWorld(Scene(t));world.Seek(1);Check(world.bullets.Count(q=>q.birth<=1)==1,"Stagger delays birth");world.Seek(4);Near(world.bullets[0].x,-50,"Line left endpoint");Near(world.bullets[2].x,50,"Line right endpoint");
            var group=new Track{id="group",kind="group",start=0,end=100,x=100,y=200,angle=90,scale=2};t=Emitter();t.x=10;t.parentId=group.id;t.speed=0;state=Scene(group,t);var p=Motion.At(t,0);Near(p.x,100,"Parent rotation X");Near(p.y,180,"Parent rotation Y");Near(p.scale,2,"Parent scale");var clones=BulletSystem.CloneTracks(state.tracks);Check(clones[1].parentId==clones[0].id&&clones[0].id!=group.id,"Copies remap parent IDs");
            t=Emitter();t.count=4;t.end=10;t.expressions["speed"]="random_range(1,9)+i*0";t.randomScope="volley";state=Scene(t);world=new BulletWorld(state);world.Seek(10);Check(world.bullets.Where(q=>q.volley==0).Select(q=>q.speed).Distinct().Count()==1,"Volley random shared across bullets");Check(world.bullets.First(q=>q.volley==0).speed!=world.bullets.First(q=>q.volley==1).speed,"Volley random changes between volleys");t.randomScope="bullet";world=new BulletWorld(state);world.Seek(0);Check(world.bullets.Select(q=>q.speed).Distinct().Count()==4,"Per-bullet random independent");
            t=Emitter();t.parentId="g";var g=new Track{id="g",kind="group",start=0,end=20,x=100,y=100};var clip=new Track{id="clip",kind="pattern",start=100,end=200,repeatCount=2,repeatGap=5,timeScale=2,children=new List<Track>{g,t}};var expanded=BulletSystem.Expand(Scene(clip));Check(expanded.tracks.Count==4,"Pattern repeats its full composition");Check(expanded.tracks[1].parentId==expanded.tracks[0].id,"Pattern references remapped");Near(expanded.tracks[0].start,100,"First loop start");Near(expanded.tracks[2].start,116,"Second loop start includes rate and gap");
            var portable=TrackPreset.Capture("loop",new[]{clip},50);Check(portable.Instantiate(300,50).Single().children.Count==2,"Nested custom preset survives round trip");
            t=Emitter();t.flightMode="aim";state=Scene(t);state.usePlayerTrace=true;state.playerTrace=new List<PlayerTracePoint>{new PlayerTracePoint{frame=0,x=0,y=100},new PlayerTracePoint{frame=500,x=100,y=100}};world=new BulletWorld(state);world.Seek(50);Check(world.bullets[0].y>90,"Preview follows recorded player path");world.Seek(450);x=world.bullets.Count;world.Seek(80);world.Seek(450);Check(world.bullets.Count==x,"Checkpoint restores simulation deterministically");
            string traceFile=Path.Combine(scratch,"trace.csv");File.WriteAllText(traceFile,"100,1,2\n101,3,4\n100,5,6\n101,7,8\n");var trace=PlayerTrace.Read(traceFile);Check(trace.Count==2&&trace[0].x==5,"R retry keeps the last recorded take");
            var demo=Emitter("behavior-demo");demo.name="减速瞄准冲刺";demo.x=240;demo.y=240;demo.end=100;demo.interval=50;demo.count=18;demo.spread=20;demo.speed=5;demo.life=180;demo.trailMode="shrink";demo.bulletActions.Add(new BulletAction{type="speed",start=0,duration=20,from=5,to=0,easing="sin-out"});demo.bulletActions.Add(new BulletAction{type="aim",start=45,duration=0,stagger=2,to=0});demo.bulletActions.Add(new BulletAction{type="speed",start=45,duration=25,stagger=2,from=0,to=6,easing="power-in"});demo.bulletActions.Add(new BulletAction{type="alpha",start=140,duration=35,from=1,to=0});
            var curve=Emitter("curve-demo");curve.name="贝塞尔阵列";curve.x=550;curve.y=200;curve.emissionShape="bezier";curve.emissionFacing="tangent";curve.count=12;curve.end=60;curve.interval=30;curve.indexDelay=1;curve.speed=1;curve.curvePoints=new List<CurvePoint>{new CurvePoint{x=-100,y=-100},new CurvePoint{x=100,y=-80},new CurvePoint{x=-100,y=80},new CurvePoint{x=100,y=100}};
            var stop=new Track{id="stop-demo",kind="control",start=110,end=110,targetSource=curve.id,controlValue=0,name="曲线弹停顿"};var split=Emitter("split-demo");split.name="分裂";split.x=400;split.y=200;split.end=0;split.count=3;split.spread=120;split.bulletActions.Add(new BulletAction{type="split",start=35,duration=0,count=5,spread=30,childSpeed=2});
            var fixture=Scene(demo,curve,stop,split);fixture.room="rAvoidance";fixture.nativeTest=new NativeTestPosition{x=400,y=500};Motion.Normalize(fixture);File.WriteAllText(Path.Combine(scratch,"scene.json"),Json.Write(fixture));
            using(var form=new BulletBehaviorForm(demo,fixture)){form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-30000,-30000);form.Show();Application.DoEvents();form.PerformLayout();using(var picture=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(picture,new Rectangle(Point.Empty,form.Size));picture.Save(Path.Combine(scratch,"behavior-editor.png"));}form.Close();}
            var actualProject=Path.Combine(root,"projects","rufmaker-demo.gm82");using(var sprites=new SpriteStore{Project=actualProject})using(var cache=new PreviewCache())using(var image=PreviewRenderer.Render(fixture,new RoomData(),new Dictionary<string,string>(),sprites,90,false,true,cache)){image.Save(Path.Combine(scratch,"simulation.png"));}
            Console.WriteLine("PASS: age curves, aim, reverse seeking, targeted commands, child birth actions, stagger, formations, parent transforms, ID remapping, random scopes, nested presets, native behavior UI and rendered fixture.");return 0;
        }catch(Exception e){Console.Error.WriteLine(e);return 1;}
    }
}
